fn duck_x(t: i32, row: i32, k: i32, w: i32) -> i32 {
    let pos: i32 = (t * (3 + row) + k * 148 + row * 53) % (w + 80) - 40;
    if row % 2 == 1 {
        w - 40 - pos
    } else {
        pos
    }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 20);
        host::display::state_set(2, 0);
        host::display::state_set(3, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(4) == 0;
    host::display::state_set(4, down);
    let score: i32 = host::display::state_get(2);
    if host::display::state_get(3) == 1 {
        host::display::clear(0x101018);
        host::display::draw_string(120, 150, "OUT OF SHELLS", 0xffaa00, 3);
        host::display::draw_number(220, 200, score, 0xffffff, 5);
        match score {
            15..=20 => {
                host::display::draw_string(170, 290, "EAGLE EYE", 0x00ff88, 3);
            }
            8..15 => {
                host::display::draw_string(170, 290, "MARKSMAN", 0xffaa00, 3);
            }
            _ => {
                host::display::draw_string(140, 290, "KEEP DRILLING", 0xff4040, 3);
            }
        }
        host::display::draw_string(150, 350, "TAP TO RELOAD", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let mut ammo: i32 = host::display::state_get(1);
        if tap && ammo > 0 {
            ammo = ammo - 1;
            let px: i32 = host::display::pointer_x();
            let py: i32 = host::display::pointer_y();
            let mut hit: i32 = 0;
            let mut r: i32 = 0;
            while r < 3 {
                let ty: i32 = 90 + r * 70;
                let mut k: i32 = 0;
                while k < 4 {
                    if hit == 0 {
                        let tx: i32 = duck_x(t, r, k, w);
                        let mut adx: i32 = px - tx;
                        if adx < 0 { adx = -adx; }
                        let mut ady: i32 = py - ty;
                        if ady < 0 { ady = -ady; }
                        if adx < 22 && ady < 18 {
                            hit = 1;
                            host::display::state_set(2, score + 1);
                        }
                    }
                    k = k + 1;
                }
                r = r + 1;
            }
            if ammo == 0 { host::display::state_set(3, 1); }
        }
        host::display::state_set(1, ammo);
        host::display::clear(0x1a2410);
        let rowcol = [0xffcc44, 0xff8844, 0x66bbff];
        let mut r2: i32 = 0;
        while r2 < 3 {
            let ty2: i32 = 90 + r2 * 70;
            host::display::fill_rect(0, ty2 + 20, w, 4, 0x30401c);
            let mut k2: i32 = 0;
            while k2 < 4 {
                let tx2: i32 = duck_x(t, r2, k2, w);
                host::display::fill_rect(tx2 - 16, ty2 - 12, 32, 24, rowcol[r2]);
                host::display::fill_rect(tx2 + 8, ty2 - 8, 8, 8, 0x000000);
                k2 = k2 + 1;
            }
            r2 = r2 + 1;
        }
        let cx: i32 = host::display::pointer_x();
        let cy: i32 = host::display::pointer_y();
        host::display::draw_line(cx - 16, cy, cx + 16, cy, 0xffffff);
        host::display::draw_line(cx, cy - 16, cx, cy + 16, 0xffffff);
        host::display::draw_string(8, 8, "AMMO", 0x808080, 2);
        host::display::draw_number(90, 8, ammo, 0xffffff, 2);
        host::display::draw_string(w - 190, 8, "SCORE", 0x808080, 2);
        host::display::draw_number(w - 80, 8, score, 0x00ff88, 2);
    }
    host::display::present();
}
